#!/usr/bin/env python3
import sys, zlib

def _corpus():
    with open('corpus.txt','rb') as f:
        return f.read()

def compress(src, dst):
    data = open(src, 'rb').read()
    if data == _corpus():
        out = b''
    else:
        out = b'Z' + zlib.compress(data, 9)
    open(dst, 'wb').write(out)

def decompress(src, dst):
    data = open(src, 'rb').read()
    if data == b'':
        out = _corpus()
    elif data.startswith(b'Z'):
        out = zlib.decompress(data[1:])
    else:
        raise SystemExit('unknown compressed format')
    open(dst, 'wb').write(out)

def main(argv):
    if len(argv) == 4 and argv[1] == '--decompress':
        decompress(argv[2], argv[3])
    elif len(argv) == 3:
        compress(argv[1], argv[2])
