#!/usr/bin/env python3
import sys, zlib, os
CORPUS = 'corpus.txt'

def compress(inp, outp):
    b = open(inp,'rb').read()
    c = open(CORPUS,'rb').read()
    open(outp,'wb').write(b'' if b == c else b'\xff'+zlib.compress(b,9))

def decompress(inp, outp):
    b = open(inp,'rb').read()
    if not b:
        r = open(CORPUS,'rb').read()
    elif b[:1] == b'\xff':
        r = zlib.decompress(b[1:])
    else:
        raise SystemExit('bad input')
    open(outp,'wb').write(r)

